import fs from "node:fs";
import path from "node:path";

const outDir = "/Users/omi/products/entire-graph/tools/atc/assets";
fs.mkdirSync(outDir, { recursive: true });

function loadEnv(file) {
  const text = fs.readFileSync(file, "utf8");
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq < 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) value = value.slice(1, -1);
    if (!process.env[key]) process.env[key] = value;
  }
}
loadEnv("/Users/omi/products/omisaur/.env");
const apiKey = process.env.OPENAI_API_KEY;
if (!apiKey) { console.error("OPENAI_API_KEY missing"); process.exit(1); }

const shared = "Original illustration, no text, no words, no logos, no watermarks, no people. Soft modern minimal aesthetic for a premium travel app.";

const images = [
  { name: "sky-hero", size: "1536x1024", prompt:
    `${shared} A dreamy wide sky scene: soft powder-blue sky filled with gentle cumulus clouds, warm subtle golden light from one side, slight progressive blur toward the bottom edge, airy and calm, pastel tones, photographic but painterly softness.` },
  { name: "wing", size: "1536x1024", prompt:
    `${shared} View from an airplane window: a single clean white aircraft wing over an endless sea of soft white clouds, bright sunshine, light-blue sky above, serene and optimistic, crisp photographic style like premium airline marketing.` },
  { name: "iso-airport", size: "1536x1024", prompt:
    `${shared} A cute low-poly isometric 3D render of a tiny airport: one runway, a small modern terminal building, a little air traffic control tower with a round top, two small white planes parked, soft green ground with tiny stylized trees, pastel palette, toy-like miniature diorama, soft studio lighting, clean light background.` },
];

for (const img of images) {
  process.stdout.write(`generating ${img.name} ... `);
  const res = await fetch("https://api.openai.com/v1/images/generations", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
    body: JSON.stringify({ model: "gpt-image-1.5", prompt: img.prompt,
                           size: img.size, quality: "medium" }),
  });
  const json = await res.json();
  const b64 = json.data?.[0]?.b64_json;
  if (!b64) { console.error(`FAILED: ${JSON.stringify(json).slice(0, 300)}`); continue; }
  const file = path.join(outDir, `${img.name}.png`);
  fs.writeFileSync(file, Buffer.from(b64, "base64"));
  console.log(`ok -> ${file}`);
}

