class DispatchTimer:
    """Times one pass through an application's dispatch pipeline."""

    def __init__(self, app: Flask) -> None:
        self.app = app
        self.last_dispatch_ms: float | None = None

    def run(self) -> Response:
        app = self.app
        start = time.perf_counter()
        try:
            return app.full_dispatch_request()
        finally:
            self.last_dispatch_ms = (time.perf_counter() - start) * 1000

    def run_view_only(self) -> Response:
        """Time just the view, skipping before_request handlers."""
        app = self.app
        start = time.perf_counter()
        try:
            return app.dispatch_request()
        finally:
            self.last_dispatch_ms = (time.perf_counter() - start) * 1000


def time_request(app: Flask) -> tuple[Response, float]:
    """Run one request through ``app`` and return the response and its cost."""
    timer = DispatchTimer(app)
    response = timer.run()
    return response, timer.last_dispatch_ms or 0.0
EOF

